// HasReportingInstallation applies the HasEdge predicate on the "reporting_installation" edge.
func HasReportingInstallation() predicate.AttributionUsageBucket {
	return predicate.AttributionUsageBucket(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ReportingInstallationTable, ReportingInstallationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasReportingInstallationWith applies the HasEdge predicate on the "reporting_installation" edge with a given conditions (other predicates).
func HasReportingInstallationWith(preds ...predicate.ReportingInstallation) predicate.AttributionUsageBucket {
	return predicate.AttributionUsageBucket(func(s *sql.Selector) {
		step := newReportingInstallationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

